action.mutation:
mutation CreateQualityReport($payload: [QualityReportCreatePayloadInput!]!) {
  mutation: createQualityReport(payload: $payload) { 
    id
    code
  }
}

mutation UpdateQualityReport($payload: [QualityReportUpdatePayloadInput!]!) {
  mutation: updateQualityReport(payload: $payload) { 
    id
    code
  }
}
